const awsGuide = 'https://docs.aws.amazon.com/aws-certification/latest/examguides/';
const azureGuide = 'https://learn.microsoft.com/en-us/credentials/certifications/exams/';
const exams = [];
let exam;

function add(code, name, level, provider, area, duration, prerequisite = '') {
  exam = {
    code, name, level, provider, area, duration, prerequisite,
    url: provider === 'AWS' ? awsGuide : azureGuide + code.toLowerCase() + '/',
    questions: []
  };
  exams.push(exam);
}

function q(area, prompt, correct, wrong1, wrong2, wrong3, reason) {
  exam.questions.push({
    id: exam.code + '-' + (exam.questions.length + 1),
    area, prompt, correct, choices: [correct, wrong1, wrong2, wrong3], reason
  });
}

